import { demoScenarios } from '../data/demo';
export function ScenarioLab(){return <main className="min-h-screen bg-[#080b1a] px-4 py-10 text-white"><div className="mx-auto max-w-5xl"><p className="text-sm font-semibold text-violet-300">Scenario Lab</p><h1 className="mt-2 text-4xl font-bold">Test the states that production systems usually miss.</h1><div className="mt-8 space-y-3">{demoScenarios.map(s=><article key={s.id} className="flex flex-col gap-4 rounded-2xl border border-white/10 bg-white/[0.04] p-5 md:flex-row md:items-center"><div className="flex-1"><div className="flex gap-2"><span className="rounded-full bg-white/10 px-2 py-1 text-xs capitalize">{s.area}</span><span className="rounded-full bg-white/10 px-2 py-1 text-xs capitalize">{s.status}</span></div><h2 className="mt-3 font-semibold">{s.title}</h2><p className="mt-1 text-sm text-white/55">{s.description}</p></div><div className="flex gap-2"><button className="rounded-lg bg-white/10 px-3 py-2 text-sm">Inspect event</button><button className="rounded-lg bg-violet-600 px-3 py-2 text-sm">Simulate</button></div></article>)}</div></div></main>}
